mapper.select:
select c.log_id, c.student_id, c.warning_id, c.intervene_id, c.knowledge_id,
       c.content, c.next_plan, c.create_by, c.create_time, s.student_name
from spas_coach_log c
left join spas_student s on s.student_id = c.student_id
left join sys_dept d on s.dept_id = d.dept_id

    AND c.student_id = #{studentId}
    AND c.warning_id = #{warningId}
    AND c.intervene_id = #{interveneId}


            AND s.dept_id in
            #{did}

        ${params.dataScope}


order by c.create_time desc
